package mx.com.mesaregia.pagos.application.service.impl;
import mx.com.mesaregia.pagos.api.request.CompensacionCreateRequest; import mx.com.mesaregia.pagos.application.service.PagoCoverageService; import mx.com.mesaregia.pagos.domain.entity.*; import mx.com.mesaregia.pagos.domain.enums.*; import mx.com.mesaregia.pagos.exception.*; import mx.com.mesaregia.pagos.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CompensacionWriteService {private final PagoRepository pagos;private final AplicacionPagoRepository apps;private final CuentaCobroRepository cuentas;private final MovimientoCuentaRepository movs;private final FolioService folios;private final PagoCoverageService coverage;public CompensacionWriteService(PagoRepository p,AplicacionPagoRepository a,CuentaCobroRepository c,MovimientoCuentaRepository m,FolioService f,PagoCoverageService pc){pagos=p;apps=a;cuentas=c;movs=m;folios=f;coverage=pc;}
 @Transactional public Resultado compensar(Long idPago,String key,CompensacionCreateRequest r){var idem=movs.findByClaveOperacion(key);if(idem.isPresent()){var m=idem.get();if(m.getTipoMovimiento()!=TipoMovimientoCuenta.COMPENSACION||m.getPago()==null||!m.getPago().getId().equals(idPago))throw new ConflictException("Idempotency-Key ya fue utilizado por otra operación");return new Resultado(m.getId(),true);}
 var pago=pagos.findById(idPago).orElseThrow(()->new ResourceNotFoundException("Pago original no encontrado"));var app=apps.findFirstByPagoId(idPago).orElseThrow(()->new ResourceNotFoundException("Aplicación del pago no encontrada"));var cuenta=cuentas.findForUpdate(app.getCuentaCobro().getId()).orElseThrow(()->new ResourceNotFoundException("Cuenta de cobro no encontrada"));if(cuenta.getEstado()==EstadoCuentaCobro.CANCELADA)throw new ConflictException("La cuenta de cobro está cancelada");var origen=movs.findFirstByPagoIdAndTipoMovimientoOrderByIdAsc(idPago,TipoMovimientoCuenta.PAGO).orElseThrow(()->new ResourceNotFoundException("Movimiento original del pago no encontrado"));var m=new MovimientoCuenta();m.setCuentaCobro(cuenta);m.setPago(pago);m.setMovimientoOrigen(origen);m.setFolio(folios.generar("MOV"));m.setTipoMovimiento(TipoMovimientoCuenta.COMPENSACION);m.setNaturaleza(NaturalezaMovimiento.CARGO);m.setMonto(r.monto());m.setDescripcion(r.motivo());m.setIdUsuarioExterno(r.idUsuarioExterno());m.setClaveOperacion(key);m=movs.saveAndFlush(m);coverage.recalcularSinPublicar(cuenta);return new Resultado(m.getId(),false);}
 public record Resultado(Long idMovimiento,boolean idempotente){}
}
